package com.jejakteknisi.mesh
import android.app.*;import android.content.*;import android.os.*;import androidx.core.app.NotificationCompat
class IntercomService:Service(){companion object{const val CH="mesh";const val ID=1606;@Volatile var engine:WifiDirectEngine?=null}
override fun onCreate(){super.onCreate();if(engine==null)engine=WifiDirectEngine(applicationContext);engine?.onStatus={notify(it)};if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel(CH,"Mesh Intercom",NotificationManager.IMPORTANCE_LOW))}
override fun onStartCommand(i:Intent?,f:Int,id:Int):Int{val n=NotificationCompat.Builder(this,CH).setSmallIcon(android.R.drawable.ic_btn_speak_now).setContentTitle("Jejak Teknisi Mesh Intercom").setContentText(engine?.status?:"Wi-Fi Direct aktif").setOngoing(true).build();if(Build.VERSION.SDK_INT>=29)startForeground(ID,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE)else startForeground(ID,n);engine?.start();return START_STICKY}
private fun notify(s:String){getSystemService(NotificationManager::class.java).notify(ID,NotificationCompat.Builder(this,CH).setSmallIcon(android.R.drawable.ic_btn_speak_now).setContentTitle("Jejak Teknisi Mesh Intercom").setContentText(s).setOngoing(true).build())};override fun onBind(i:Intent?):IBinder?=null;override fun onDestroy(){engine?.stop();engine=null;super.onDestroy()}}
